import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import curatedGuides from '../data/curated-guides.mjs';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const out = path.join(root, 'dist');
const domain = 'https://www.obdkodu.com';
const catalog = JSON.parse(fs.readFileSync(path.join(root, 'data/catalog.json'), 'utf8'));
const guides = [...JSON.parse(fs.readFileSync(path.join(root, 'data/guides.json'), 'utf8')), ...curatedGuides];
if (new Set(guides.map(x => x.code)).size !== guides.length) throw new Error('Duplicate guide code');
const guideMap = new Map(guides.map(x => [x.code, x]));
const catalogMap = new Map(catalog.map(x => [x.code, x]));
const countLabel = catalog.length.toLocaleString('tr-TR');
const genericCount = catalog.filter(x => x.scope === 'generic').length.toLocaleString('tr-TR');
const e = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const j = value => JSON.stringify(value).replace(/</g, '\\u003c');
const list = (items, cls = '') => `<ul class="${cls}">${items.map(x => `<li>${e(x)}</li>`).join('')}</ul>`;
const url = p => domain + p;
const write = (route, content) => {
  const target = path.join(out, route.replace(/^\//, ''), 'index.html');
  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.writeFileSync(target, content, 'utf8');
};

if (out !== path.join(root, 'dist')) throw new Error('Unexpected output path');
fs.rmSync(out, { recursive: true, force: true });
fs.mkdirSync(path.join(out, 'assets'), { recursive: true });
for (const f of ['site.css', 'site.js', 'multi-code.js', 'favicon.svg', 'og.svg', 'og.png']) fs.copyFileSync(path.join(root, 'assets', f), path.join(out, 'assets', f));
fs.cpSync(path.join(root,'assets/fonts'),path.join(out,'assets/fonts'),{recursive:true});
fs.copyFileSync(path.join(root, 'data/catalog.json'), path.join(out, 'assets/catalog.json'));
fs.writeFileSync(path.join(out, 'assets/guide-codes.json'), JSON.stringify(guides.map(x => x.code)));

const categories = [
  { id:'P', label:'Motor & aktarma', count:'P kodları', icon:'⌁', text:'Motor, emisyon, yakıt ve şanzımanla ilgili kayıtlar.', color:'peach' },
  { id:'B', label:'Gövde & güvenlik', count:'B kodları', icon:'◇', text:'Hava yastığı, konfor ve gövde elektroniği sistemleri.', color:'blue' },
  { id:'C', label:'Şasi & yol tutuş', count:'C kodları', icon:'◎', text:'ABS, fren, direksiyon ve şasi denetimleri.', color:'lavender' },
  { id:'U', label:'Ağ & iletişim', count:'U kodları', icon:'↗', text:'Kontrol modülleri arasındaki veri iletişimi.', color:'mint' }
];
const featured = ['P0420','P0300','P0171','P0128','P0442','P0700'];
const key = c => guideMap.get(c);
const icon = (name, size = 20) => {
  const shapes = {
    search:'<circle cx="11" cy="11" r="6.5"/><path d="m16 16 5 5"/>',
    arrow:'<path d="M4 12h15m-6-6 6 6-6 6"/>',
    chevron:'<path d="m6 9 6 6 6-6"/>',
    menu:'<path d="M4 7h16M4 12h16M4 17h16"/>',
    close:'<path d="M5 5l14 14M19 5 5 19"/>',
    check:'<path d="m4 12 5 5L20 6"/>',
    spark:'<path d="m12 2 1.9 6.1L20 10l-6.1 1.9L12 18l-1.9-6.1L4 10l6.1-1.9L12 2Z"/>',
    copy:'<rect x="8" y="8" width="12" height="12" rx="2"/><path d="M16 8V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h3"/>'
  };
  return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${shapes[name]}</svg>`;
};
const cta = (text, href, secondary = false) => `<a class="button ${secondary ? 'button-secondary' : 'button-primary'}" href="${href}"><span>${e(text)}</span>${icon('arrow', 18)}</a>`;
const crumbsHtml = crumbs => `<nav class="breadcrumbs wrap" aria-label="İçerik yolu"><a href="/">Ana sayfa</a>${crumbs.map((c, i) => `<span aria-hidden="true">/</span>${i === crumbs.length - 1 ? `<span aria-current="page">${e(c.name)}</span>` : `<a href="${c.path}">${e(c.name)}</a>`}`).join('')}</nav>`;
const crumbSchema = crumbs => ({'@type':'BreadcrumbList', itemListElement:[{ '@type':'ListItem', position:1, name:'Ana sayfa', item:url('/') }, ...crumbs.map((c,i)=>({'@type':'ListItem',position:i+2,name:c.name,item:url(c.path)}))]});
const faqSchema = faqs => ({'@type':'FAQPage', mainEntity:faqs.map(([q,a])=>({'@type':'Question',name:q,acceptedAnswer:{'@type':'Answer',text:a}}))});
const faqHtml = faqs => `<div class="faq-stack">${faqs.map(([q,a])=>`<details class="faq-item"><summary>${e(q)}<span class="faq-plus" aria-hidden="true">+</span></summary><p>${e(a)}</p></details>`).join('')}</div>`;
const header = () => `<header class="site-header"><div class="header-inner wrap"><a class="brand" href="/" aria-label="OBDKODU ana sayfa"><span class="brand-mark"><span></span><span></span><span></span><span></span></span><span>obd<span class="brand-accent">kodu</span><small>.com</small></span></a><nav class="desktop-nav" aria-label="Ana menü"><a href="/ariza-kodlari/">Arıza kodları</a><a href="/kodlari-birlikte-yorumla/">Kodları birlikte oku</a><a href="/sistemler/">Sistemler</a><a href="/rehber/">Rehber</a><a href="/sss/">Sık sorulanlar</a></nav><a class="header-search" href="/ariza-kodlari/">Kod ara ${icon('arrow',16)}</a><button class="menu-toggle" type="button" aria-label="Menüyü aç" aria-expanded="false" aria-controls="mobile-nav">${icon('menu',22)}</button></div><nav class="mobile-nav" id="mobile-nav" aria-label="Mobil menü" hidden><a href="/ariza-kodlari/">Arıza kodları</a><a href="/kodlari-birlikte-yorumla/">Kodları birlikte oku</a><a href="/sistemler/">Sistemler</a><a href="/rehber/">Rehber</a><a href="/sss/">Sık sorulanlar</a></nav></header>`;
const footer = () => `<footer class="site-footer"><div class="wrap footer-top"><div class="footer-brand"><a class="brand" href="/"><span class="brand-mark"><span></span><span></span><span></span><span></span></span><span>obd<span class="brand-accent">kodu</span><small>.com</small></span></a><p>Arıza kodunu okumak ilk adım. Doğru teşhis, veriyi birlikte yorumlamakla başlar.</p></div><div class="footer-links"><div><strong>Keşfet</strong><a href="/ariza-kodlari/">Kod dizini</a><a href="/kodlari-birlikte-yorumla/">Kodları birlikte oku</a><a href="/sistemler/">Sistemler</a><a href="/rehber/">Rehberler</a><a href="/sss/">Sık sorulanlar</a></div><div><strong>OBDKODU</strong><a href="/hakkimizda/">Hakkımızda</a><a href="/yontem-ve-kaynaklar/">Yöntem ve kaynaklar</a><a href="/iletisim/">İletişim</a><a href="/gizlilik/">Gizlilik</a></div></div></div><div class="wrap footer-bottom"><span>© ${new Date().getFullYear()} OBDKODU</span><span>Bilgi amaçlıdır; araç üreticisinin servis dokümanı ve uzman kontrolü esas alınır.</span><a href="#ust">Yukarı dön ↑</a></div></footer>`;
const page = ({title, description, route, body, crumbs=[], graph=[], noindex=false}) => {
  const canonical = url(route);
  const jsonGraph = [
    {'@type':'WebSite','@id':url('/#website'),name:'OBDKODU',url:url('/'),inLanguage:'tr-TR',description:'OBD arıza kodları, belirtiler ve teşhis adımları için Türkçe kaynak.'},
    {'@type':'WebPage','@id':canonical+'#webpage',url:canonical,name:title,description,inLanguage:'tr-TR',isPartOf:{'@id':url('/#website')}},
    ...(crumbs.length ? [crumbSchema(crumbs)] : []), ...graph
  ];
  return `<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f8f7f3"><meta name="color-scheme" content="light"><title>${e(title)}</title><meta name="description" content="${e(description)}"><meta name="robots" content="${noindex ? 'noindex,follow' : 'index,follow,max-image-preview:large'}"><link rel="canonical" href="${canonical}"><link rel="icon" type="image/svg+xml" href="/assets/favicon.svg"><link rel="stylesheet" href="/assets/site.css"><meta property="og:type" content="website"><meta property="og:locale" content="tr_TR"><meta property="og:site_name" content="OBDKODU"><meta property="og:title" content="${e(title)}"><meta property="og:description" content="${e(description)}"><meta property="og:url" content="${canonical}"><meta property="og:image" content="${url('/assets/og.png')}"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta name="twitter:card" content="summary_large_image"><script type="application/ld+json">${j({'@context':'https://schema.org','@graph':jsonGraph})}</script><script src="/assets/site.js" defer></script></head><body id="ust">${header()}${crumbs.length ? crumbsHtml(crumbs) : ''}<main>${body}</main>${footer()}</body></html>`;
};
const codeLink = code => `<a href="/ariza-kodlari/${code.toLowerCase()}/">${code}</a>`;
const codeCard = (code, index=0) => { const d=key(code); return `<a class="code-card" href="/ariza-kodlari/${code.toLowerCase()}/"><span class="code-card-top"><span class="code-glyph">${String(index+1).padStart(2,'0')}</span><span class="code-card-arrow">↗</span></span><strong>${code}</strong><span>${e(d.name)}</span><span class="code-card-bottom">${e(d.affectedSystem || 'OBD-II')} <b>›</b></span></a>`; };

const homeFaqs = [
  ['OBD arıza kodu tek başına arızalı parçayı söyler mi?', 'Hayır. Kod, kontrol ünitesinin hangi sistemde beklenmeyen bir durum gördüğünü belirtir. Kesin teşhis için diğer kodlar, donma karesi, canlı veriler ve araç üreticisinin prosedürü birlikte değerlendirilir.'],
  ['Motor arıza lambası yanıp sönüyorsa ne yapmalıyım?', 'Yanıp sönen lamba ciddi tekleme gibi katalizöre zarar verebilecek bir duruma işaret edebilir. Güvenli bir yerde durun, aracı zorlamayın ve profesyonel yardım alın.'],
  ['Kodu silmek arızayı çözer mi?', 'Hayır. Kodun silinmesi yalnızca kaydı temizler; neden devam ediyorsa kod geri dönebilir. Ayrıca donma karesi gibi teşhis verileri kaybolabilir.']
];
const home = `<section class="hero"><div class="wrap hero-grid"><div class="hero-copy"><span class="eyebrow"><span class="eyebrow-line"></span> TÜRKÇE OBD ARIZA KODU REHBERİ</span><h1>Arıza kodu göründü.<br><em>Şimdi neye bakacağını bil.</em></h1><p>Gösterge panelindeki uyarıyı tahmine bırakma. Kodu ara; anlamını, olası nedenleri ve doğru teşhis sırasını anlaşılır biçimde gör.</p><form class="hero-search search-form" role="search" data-search-form><label class="sr-only" for="home-search">OBD kodu veya belirti ara</label>${icon('search',23)}<input id="home-search" name="q" autocomplete="off" placeholder="Örn. P0420, tekleme, oksijen sensörü" aria-label="OBD kodu veya belirti ara"><button type="submit">Kodu bul ${icon('arrow',18)}</button><div class="suggestions" data-suggestions hidden></div></form><div class="hero-examples"><span>Hızlı bak:</span>${['P0420','P0300','P0171'].map(codeLink).join('')}</div><div class="hero-proof"><div class="proof-icon">${icon('check',18)}</div><span><strong>Parça tahmini değil, teşhis yolu.</strong><br>Önce veriyi oku, sonra kontrol et.</span></div></div><div class="hero-visual" aria-label="P0420 örnek teşhis kartı"><div class="visual-orbit orbit-a"></div><div class="visual-orbit orbit-b"></div><div class="visual-dots"></div><div class="diagnostic-card"><div class="diag-top"><span><span class="live-dot"></span> ÖRNEK TEŞHİS KARTI</span><span class="diag-top-mark">01 / 03</span></div><div class="diag-code">P0420<span>↗</span></div><h2>Katalizör verimliliği<br>eşik altında</h2><div class="diag-rule"></div><div class="diag-step"><span>01</span><p>Önce eşlik eden tekleme ve karışım kodlarını oku.</p></div><div class="diag-step"><span>02</span><p>Egzoz kaçağı ve O₂ sensörü verilerini doğrula.</p></div><div class="diag-step"><span>03</span><p>Konvertörü ancak ölçümle değerlendir.</p></div><a href="/ariza-kodlari/p0420/">P0420 rehberine git ${icon('arrow',18)}</a></div><div class="float-note"><span class="float-symbol">✳</span><span>Tek kod.<br><strong>Daha iyi sorular.</strong></span></div></div></div><div class="wrap hero-bottom"><span>OBD-II KOD DİZİNİ</span><span>ANLA <b>→</b> KONTROL ET <b>→</b> DOĞRULA</span><span>↓ KEŞFET</span></div></section>
<section class="section featured-section"><div class="wrap"><div class="section-heading"><div><span class="eyebrow">SIK ARANAN KODLAR</span><h2>En çok merak edilenler,<br><em>en doğru başlangıçla.</em></h2></div><p>Bir kodun anlamı ilk ipucudur. Her rehberde belirtileri, olası nedenleri ve kontrol sırasını birlikte bul.</p></div><div class="code-grid">${featured.map(codeCard).join('')}</div><div class="section-end">${cta('Tüm kodları keşfet','/ariza-kodlari/',true)}</div></div></section>
<section class="section systems-section"><div class="wrap systems-layout"><div class="systems-intro"><span class="eyebrow">NEREDEN BAŞLAMALI?</span><h2>Kodun harfi,<br><em>sistemin ipucu.</em></h2><p>OBD kodları ilk harfine göre dört ana aileye ayrılır. Kodu okuyup doğru sisteme yönelmek teşhisi hızlandırır.</p>${cta('Sistemleri incele','/sistemler/')}</div><div class="system-grid">${categories.map(c=>`<a class="system-card ${c.color}" href="/ariza-kodlari/${c.id.toLowerCase()}/"><span class="system-head"><span class="system-icon">${c.icon}</span><span class="system-letter">${c.id}</span></span><span><small>${c.count}</small><strong>${c.label}</strong><p>${c.text}</p></span><span class="system-arrow">↗</span></a>`).join('')}</div></div></section>
<section class="section method-section"><div class="wrap"><div class="section-heading narrow"><div><span class="eyebrow">KISA YOL DEĞİL, DOĞRU SIRA</span><h2>İyi teşhis <em>üç adımda</em> başlar.</h2></div></div><div class="method-grid"><div><span class="method-index">01 <i></i></span><h3>Kodu ve koşulu kaydet</h3><p>Bekleyen ve kayıtlı kodları, donma karesini ve lambanın davranışını not al. Kodu hemen silmek veriyi kaybettirir.</p></div><div><span class="method-index">02 <i></i></span><h3>Olasılıkları sırala</h3><p>Belirti, eşlik eden kodlar ve canlı verilerle olası nedenleri daralt. Tek bir koda bakarak parça değiştirme.</p></div><div><span class="method-index">03 <i></i></span><h3>Onarımı doğrula</h3><p>Gerekli ölçümü ve onarımı yap. Ardından çalışma koşullarında tekrar test ederek arızanın dönmediğini kontrol et.</p></div></div><div class="method-footer"><span>Bir sonraki adımı öğrenmek için</span><a href="/rehber/kod-okunduktan-sonra/">Teşhis rehberini oku ${icon('arrow',18)}</a></div></div></section>
<section class="multi-teaser"><div class="wrap multi-teaser-grid"><div><span class="eyebrow">BİRDEN FAZLA KOD MU ÇIKTI?</span><h2>Kodları tek tek değil,<br><em>birlikte düşün.</em></h2><p>P0300 ile P0420 aynı anda göründüğünde sıranın önemi değişir. Kodlarını gir; hangi ilişkilere önce bakılabileceğini ve nedenini gör.</p>${cta('Kodları birlikte yorumla','/kodlari-birlikte-yorumla/')}</div><div class="multi-teaser-card"><span>ÖRNEK · AYNI ANDA KAYDEDİLEN KODLAR</span><div><b>P0300</b><span>Tekleme</span><i>+</i><b>P0420</b><span>Katalizör verimi</span></div><p><strong>İlk soru:</strong> Aktif tekleme katalizör sonucunu etkilemiş olabilir mi?</p></div></div></section>
<section class="section faq-section"><div class="wrap faq-layout"><div><span class="eyebrow">SIK SORULANLAR</span><h2>Önce akıldaki<br><em>soruları giderelim.</em></h2><p>Arıza kodları hakkında en temel sorulara kısa, doğrudan yanıtlar.</p>${cta('Tüm sorular','/sss/',true)}</div>${faqHtml(homeFaqs)}</div></section>
<section class="closing-band"><div class="wrap closing-inner"><div><span class="eyebrow">HAZIRSAN BAŞLAYALIM</span><h2>Kodun ne söylüyor?</h2><p>Bir harf, dört rakam. Daha net bir teşhis için ilk adım.</p></div>${cta('Kod dizinini aç','/ariza-kodlari/')}</div></section>`;
write('/', page({title:'OBD Arıza Kodları ve Türkçe Teşhis Rehberi | OBDKODU',description:'OBD-II arıza kodunu ara. Anlamını, belirtilerini, olası nedenlerini ve güvenli teşhis adımlarını Türkçe öğren. P, B, C ve U kod dizini.',route:'/',body:home,graph:[faqSchema(homeFaqs)]}));

const catalogIntro = `<section class="page-hero light-hero"><div class="wrap"><span class="eyebrow">OBD-II KOD DİZİNİ</span><h1>Bir koddan <em>daha fazlası.</em></h1><p>${countLabel} kod kaydında isim veya numarayla ara. ${genericCount} genel OBDex kodu ile yerel Türkçe kayıtlar bir arada; ayrıntılı rehberi olan kodlarda belirtiler, olası nedenler ve doğrulama adımlarına geç.</p><div class="catalog-search search-form" role="search"><label class="sr-only" for="catalog-search">Kod veya anahtar kelime ara</label>${icon('search',22)}<input id="catalog-search" type="search" autocomplete="off" placeholder="Kod veya anahtar kelime ara — örn. P0171, EGR, ABS" data-catalog-search><kbd>/</kbd></div><div class="filter-row" role="group" aria-label="Kod ailesi filtresi"><button class="filter-pill active" type="button" data-filter="ALL">Tümü</button>${categories.map(c=>`<button class="filter-pill" type="button" data-filter="${c.id}">${c.id} · ${c.label}</button>`).join('')}</div><div class="filter-row filter-secondary" role="group" aria-label="İçerik filtresi"><button class="filter-pill active" type="button" data-scope="ALL">Tüm kayıtlar</button><button class="filter-pill" type="button" data-scope="GUIDE">Ayrıntılı rehberler</button><button class="filter-pill" type="button" data-scope="TR">Türkçe adlar</button></div></div></section><section class="section catalog-section"><div class="wrap"><div class="catalog-bar"><div><span class="eyebrow">KOD LİSTESİ</span><h2>Aradığın kodu bul.</h2></div><span id="catalog-count" aria-live="polite">Kodlar yükleniyor…</span></div><div class="catalog-results" id="catalog-results" aria-live="polite">${featured.map(c=>`<a class="catalog-row" href="/ariza-kodlari/${c.toLowerCase()}/"><strong>${c}</strong><span>${e(key(c).name)}</span><small>Ayrıntılı rehber ↗</small></a>`).join('')}</div><button class="load-more" id="load-more" type="button" hidden>Daha fazla kod göster ↓</button><p class="catalog-note">İngilizce adlar OBDex kaynak adıdır. Rehberi olmayan kayıtlar yalnızca dizinde gösterilir; bunları kesin onarım önerisi olarak değerlendirmeyin. <a href="/yontem-ve-kaynaklar/">Veri kapsamı ve kaynaklar ↗</a></p></div></section>`;
write('/ariza-kodlari/', page({title:'OBD Arıza Kodları Listesi: P, B, C ve U | OBDKODU',description:`${countLabel} OBD kod kaydında numara veya adla arama yapın. P motor, B gövde, C şasi ve U iletişim kodları; seçilmiş kodlar için Türkçe teşhis rehberleri.`,route:'/ariza-kodlari/',body:catalogIntro,crumbs:[{name:'Arıza kodları',path:'/ariza-kodlari/'}]}));
const multiRoute='/kodlari-birlikte-yorumla/';
const multiBody=`<section class="page-hero multi-hero"><div class="wrap"><span class="eyebrow">BİRLİKTE TEŞHİS İÇİN İLK ADIM</span><h1>Birden fazla kodu<br><em>birlikte oku.</em></h1><p>Bir kod başka bir sorunun sonucu olabilir. En fazla altı kod gir; aralarındaki bilinen ilişkileri ve hangi veriyi önce kaydetmen gerektiğini gör.</p></div></section><section class="section multi-workspace"><div class="wrap multi-layout"><div class="multi-input-card"><span class="eyebrow">01 / KODLARI EKLE</span><h2>Okuyucunda ne göründü?</h2><p>Kodları virgül, boşluk veya yeni satırla ayır. Örneğin <strong>P0300, P0420</strong>.</p><label for="multi-codes">OBD arıza kodları</label><textarea id="multi-codes" rows="4" maxlength="120" spellcheck="false" placeholder="P0300, P0420, P0171" aria-describedby="multi-format"></textarea><small id="multi-format">P, B, C veya U ile başlayan beş karakterli kodlar kabul edilir.</small><button class="button button-primary" type="button" id="multi-analyze">Kodları yorumla ${icon('arrow',18)}</button><div class="multi-examples"><span>Örnek dene:</span><button type="button" data-multi-example="P0300,P0420">P0300 + P0420</button><button type="button" data-multi-example="P0171,P0300">P0171 + P0300</button><button type="button" data-multi-example="P0562,U0101">P0562 + U0101</button></div></div><div class="multi-explain"><span class="eyebrow">02 / ÖNCE VERİYİ KORU</span><h2>Kod sırası neden önemli?</h2><p>Örneğin aktif tekleme katalizör verimini etkileyebilir; düşük voltaj birden çok modülde iletişim hatası oluşturabilir. Önce ortak nedeni araştırmak gereksiz parça değişimini önler.</p><ul><li>Tüm kodları ve hangi modülde kaydedildiklerini not et.</li><li>Donma karesi, lamba davranışı ve belirtileri kaydet.</li><li>Araç marka/model/motor bilgisine göre üretici test sırasını izle.</li></ul><p class="multi-explain-note">Bu araç olası ilişkileri gösterir; otomatik arıza teşhisi yapmaz.</p></div></div><div class="wrap multi-results" id="multi-results" aria-live="polite" hidden></div></section><section class="section multi-seo"><div class="wrap"><span class="eyebrow">ÖRNEK OKUMA SIRASI</span><h2>İki kod aynı anda çıkarsa?</h2><div class="multi-examples-grid"><article><strong>P0300 + P0420</strong><p>Aktif tekleme, katalizör ölçümünü etkileyebilir. Tekleme ve yakıt karışımı sorunlarını incelemeden konvertör kararı verme.</p><a href="/ariza-kodlari/p0300/">P0300 rehberi ↗</a></article><article><strong>P0171 + P0300</strong><p>Fakir karışım ile tekleme ortak bir hava veya yakıt besleme sorunundan kaynaklanabilir. Emme kaçağı ve yakıt düzeltmelerini birlikte incele.</p><a href="/ariza-kodlari/p0171/">P0171 rehberi ↗</a></article><article><strong>P0562 + U0101</strong><p>Düşük sistem voltajı modül iletişimini etkileyebilir. Önce akü, şarj ve besleme koşullarını doğrula.</p><a href="/ariza-kodlari/?q=P0562">P0562 dizin kaydı ↗</a></article></div><p class="multi-method-link"><a href="/rehber/kod-okunduktan-sonra/">Kodlar okunduktan sonra ne yapmalı? →</a></p></div></section><script src="/assets/multi-code.js" defer></script>`;
write(multiRoute,page({title:'Birden Fazla OBD Kodunu Birlikte Yorumla | OBDKODU',description:'Birden fazla OBD arıza kodu mu çıktı? Kodları birlikte girin; olası ilişkileri, ilk kontrol sırasını ve ayrıntılı Türkçe rehberleri görün.',route:multiRoute,body:multiBody,crumbs:[{name:'Kodları birlikte oku',path:multiRoute}]}));

const systemsBody = `<section class="page-hero"><div class="wrap"><span class="eyebrow">KOD AİLELERİ</span><h1>İlk harf, <em>ilk yön.</em></h1><p>OBD-II kodları hangi araç sisteminde sorun algılandığını ilk karakterde söyler. Aynı kod farklı marka ve modellerde farklı koşullarda ortaya çıkabilir.</p></div></section><section class="section systems-directory"><div class="wrap">${categories.map(c=>`<article class="family-block ${c.color}"><div class="family-letter">${c.id}</div><div><span class="eyebrow">${c.count.toUpperCase()}</span><h2>${c.label}</h2><p>${c.text}</p><p>${c.id==='P'?'P0, P2 ve P3 aileleri genel güç aktarma kodlarını kapsar; P1 gibi üreticiye özgü kodlarda marka ve model bilgisi gerekir.':c.id==='B'?'Airbag gibi güvenlik sistemlerinde ölçüm ve onarım eğitimli teknisyen tarafından yapılmalıdır.':c.id==='C'?'Fren ve yönlendirme sistemlerindeki uyarılar sürüş güvenliğini etkileyebilir; belirtiler varsa aracı kullanmayı bırakın.':'Düşük akü gerilimi ve bağlantı sorunları birden çok modülde iletişim kodu oluşturabilir.'}</p><a href="/ariza-kodlari/${c.id.toLowerCase()}/">${c.id} kodlarını gör ${icon('arrow',18)}</a></div></article>`).join('')}</div></section>`;
write('/sistemler/', page({title:'OBD Kod Aileleri: P, B, C ve U Ne Demek? | OBDKODU',description:'P, B, C ve U OBD arıza kodlarının hangi sistemlere ait olduğunu öğrenin. Motor, gövde, şasi ve iletişim kodları için Türkçe açıklamalar.',route:'/sistemler/',body:systemsBody,crumbs:[{name:'Sistemler',path:'/sistemler/'}]}));

const familyNotes = {
  P:{lead:'P kodları motor, yakıt, emisyon ve aktarma sistemindeki izleme sonuçlarını kapsar. Tekleme, hava-yakıt karışımı, katalizör ve şanzıman kodları bu ailede sık görülür.',checks:['Önce kayıtlı ve bekleyen tüm kodları birlikte kaydet.','Donma karesi ve canlı veriyi arızanın görüldüğü koşullarla eşleştir.','Yakıt, hava, ateşleme ve egzoz nedenlerini ölçümle ayır.'],tip:'Yanıp sönen motor arıza lambası aktif teklemeye işaret edebilir; güvenli yerde durup aracı zorlamayın.'},
  B:{lead:'B kodları gövde elektroniği, konfor ve bazı güvenlik sistemleriyle ilişkilidir. Hava yastığı uyarıları bu grupta olabilir; temel OBD okuyucular tüm B kodlarını göstermeyebilir.',checks:['Kodun hangi gövde modülünden geldiğini doğrula.','Akü gerilimi, sigorta ve konnektör durumunu servis şemasına göre incele.','SRS ve emniyet kemeri gergisi devrelerinde eğitimli teknisyen prosedürünü uygula.'],tip:'Hava yastığı devrelerine sıradan ölçüm veya müdahale uygulamayın.'},
  C:{lead:'C kodları ABS, fren, direksiyon ve yol tutuş sistemleriyle ilgilidir. Bir sensör arızası başka güvenlik uyarılarını da tetikleyebilir.',checks:['ABS/ESP modülündeki tüm kodları ve canlı tekerlek hızı verilerini kaydet.','Besleme, konnektör, sensör ve mekanik parçaları birlikte değerlendir.','Onarımdan sonra uygun koşullarda sistem testini doğrula.'],tip:'Fren veya direksiyon davranışı değiştiyse aracı kullanmayı bırakıp uzman desteği alın.'},
  U:{lead:'U kodları araçtaki kontrol modülleri arasındaki iletişimle ilgilidir. Bir modülün iletişimi kesildiğinde birden çok kontrol ünitesi aynı olayı kaydedebilir.',checks:['Kodun hangi modüllerde ve ne zaman oluştuğunu karşılaştır.','Akü, şarj sistemi, sigorta ve ortak şase noktalarını ölç.','CAN hattı ve modül testlerini üretici bağlantı şemasına göre uygula.'],tip:'Tek bir U koduyla doğrudan kontrol ünitesi değiştirmeyin.'}
};
for (const c of categories){
 const note=familyNotes[c.id];
 const route=`/ariza-kodlari/${c.id.toLowerCase()}/`;
 const selected=guides.filter(x=>x.category===c.id);
 const body=`<section class="page-hero family-hero ${c.color}"><div class="wrap family-hero-grid"><div><span class="eyebrow">${c.id} KOD AİLESİ</span><h1>${c.label}<br><em>arıza kodları.</em></h1><p>${note.lead}</p><div class="family-hero-actions">${cta(`${c.id} kodlarında ara`,`/ariza-kodlari/?kategori=${c.id}`)}<span>${catalog.filter(x=>x.category===c.id).length.toLocaleString('tr-TR')} dizin kaydı</span></div></div><div class="family-hero-symbol">${c.id}</div></div></section><section class="section"><div class="wrap"><div class="section-heading"><div><span class="eyebrow">SEÇİLMİŞ REHBERLER</span><h2>Bu ailede <em>ayrıntılı kodlar.</em></h2></div><p>Her kod için anlam, belirtiler, olası nedenler ve kontrol sırası.</p></div><div class="code-grid">${selected.map((x,i)=>codeCard(x.code,i)).join('')}</div></div></section><section class="section family-help"><div class="wrap family-help-grid"><div><span class="eyebrow">TEŞHİS YAKLAŞIMI</span><h2>İlk bakışta<br><em>neye dikkat etmeli?</em></h2><p>${note.tip}</p></div><ol class="step-list">${note.checks.map((step,i)=>`<li><span>0${i+1}</span><p>${step}</p></li>`).join('')}</ol></div></section>`;
 write(route,page({title:`${c.id} Kodları: ${c.label} Arıza Kodları | OBDKODU`,description:`${c.id} OBD kodları ${c.label.toLocaleLowerCase('tr-TR')} sistemleriyle ilgilidir. ${selected.length} ayrıntılı Türkçe rehberi ve kod dizinini inceleyin.`,route,body,crumbs:[{name:'Arıza kodları',path:'/ariza-kodlari/'},{name:`${c.id} kodları`,path:route}]}));
}

const editorial = {
 P0420:{ summary:'Katalizör verimliliği beklenen eşiğin altında ölçüldü. Bu, konvertörün tek başına arızalı olduğunu kanıtlamaz.', first:'Önce tekleme, yakıt karışımı ve egzoz kaçağı sorunlarını ele. Ardından ön ve arka oksijen sensörü sinyallerini üretici prosedürüne göre karşılaştır.', steps:['Eşlik eden kodları ve donma karesini kaydet; aktif tekleme veya karışım kodu varsa önce onu çöz.','Konvertör öncesindeki egzoz kaçaklarını ve sensör kablolarını kontrol et.','Tam ısınmış motorda ön/arka oksijen sensörü davranışını ve yakıt düzeltmelerini incele.','Konvertörü ancak test sonuçları destekliyorsa değerlendir; onarım sonrası sürüş döngüsüyle doğrula.'], caution:'Tek başına P0420 ile katalitik konvertör değiştirmek gereksiz masrafa yol açabilir.'},
 P0300:{ summary:'Kontrol ünitesi birden fazla silindirde veya rastgele tekleme algıladı. Tek bir parçaya işaret etmez.', first:'Lamba yanıp sönüyorsa aracı güvenli yerde durdur. Kodların hangi devir ve yükte oluştuğunu inceleyip ateşleme, yakıt ve emme tarafını sırayla kontrol et.', steps:['Yanıp sönen motor lambası varsa aracı zorlamadan güvenli yerde dur.','Silindir bazlı P0301–P030x kodları, donma karesi ve tekleme sayaçlarını oku.','Buji ve bobinleri, enjektörleri, hava kaçaklarını ve yakıt basıncını ölçümle değerlendir.','Gerekirse kompresyon/kaçak testi uygula; onarım sonrası tekleme sayaçlarıyla doğrula.'], caution:'Aktif teklemeyle sürüş katalitik konvertöre zarar verebilir.'},
 P0171:{ summary:'Bank 1 tarafındaki karışım, kontrol ünitesinin düzeltmesine rağmen fakir kalıyor.', first:'Rölanti ve yük altında kısa/uzun dönem yakıt düzeltmelerini karşılaştır. Hava kaçağı ve yakıt beslemesini ölçmeden oksijen sensörü değiştirme.', steps:['Donma karesini, diğer kodları ve yakıt düzeltmelerini kaydet.','Emme hattı, PCV ve vakum bağlantılarında kaçak ara; gerekirse duman testi uygula.','MAF/MAP verisi ve yakıt basıncını üretici değerleriyle karşılaştır.','Onarım sonrası farklı yüklerde yakıt düzeltmelerinin normale döndüğünü doğrula.'], caution:'“Fakir karışım” kodu oksijen sensörünün mutlaka arızalı olduğu anlamına gelmez.'},
 P0442:{ summary:'EVAP yakıt buharı sisteminde küçük bir kaçak algılandı.', first:'Depo kapağı ve contasını gözle kontrol et. Kod tekrar ediyorsa EVAP hatlarını ve valflerini uygun ekipmanla test et.', steps:['Depo kapağının doğru kapandığını, contasının ve dolum ağzının sağlam olduğunu kontrol et.','Buhar hortumları ve kanister bağlantılarını görsel olarak incele.','Purge ve vent valflerini üretici test prosedürüyle kontrol et.','Gerekirse düşük basınçlı EVAP duman testi yap; onarım sonrası monitör sonucunu izle.'], caution:'Yakıt buharı çevresinde açık alev veya kıvılcım oluşturma.'},
 P0455:{ summary:'EVAP sisteminde büyük kaçak veya sistemin sızdırmazlık testini tamamlayamaması algılandı.', first:'Önce depo kapağı ve görünür hortum bağlantılarını kontrol et. Ardından valfler ve sistem bütünlüğünü test et.', steps:['Depo kapağını, contasını ve dolum ağzını kontrol et.','Yakıt buharı hortumlarında çıkma veya çatlak ara.','Purge ve vent valflerini komut/veriyle test et.','Uygun EVAP duman testiyle kaçak yerini doğrula ve monitörü tekrar çalıştır.'], caution:'Yakıt kokusu belirginse aracı güvenli bir yerde durdurup uzman kontrolü al.'},
 P0128:{ summary:'Motor, beklenen sürede hedef soğutma suyu sıcaklığına ulaşmadı.', first:'Canlı sıcaklık verisini gerçek motor sıcaklığıyla karşılaştır; termostatı doğrulamadan değiştirme.', steps:['Soğuk motorda ECT verisini ortam sıcaklığıyla karşılaştır.','Soğutma suyu seviyesini ve kaçakları kontrol et.','Isınma eğrisini ve termostat açma davranışını izle.','Onarım sonrası normal çalışma sıcaklığına ulaşma süresini doğrula.'], caution:'Soğutma sistemi sıcakken kapağı açma.'},
 P0401:{ summary:'EGR akışı, kontrol ünitesinin beklediğinden düşük ölçüldü.', first:'EGR komutu ve gerçek tepkiyi karşılaştır; kurumla tıkalı geçiş, valf ve kumanda devresini ayır.', steps:['Eşlik eden kodları ve çalışma koşullarını kaydet.','EGR valfinin komuta yanıtını canlı veride incele.','Kanallardaki kurum birikimini ve vakum/elektrik kumandasını kontrol et.','Onarım veya temizlik sonrası adaptasyon ve sürüş testi yap.'], caution:'EGR valfini değiştirmeden önce tıkalı kanal olasılığını ele.'},
 P0101:{ summary:'MAF hava akış ölçümü, motorun beklenen çalışma aralığıyla uyuşmuyor.', first:'Hava filtresi, emme hattı ve MAF canlı verisini kontrol et; sensörü ancak testle doğruladıktan sonra değiştir.', steps:['Hava filtresi, emme hortumu ve sensör sonrası kaçakları incele.','Rölanti ve yükte MAF verisini motor özellikleriyle karşılaştır.','Besleme, şase ve sinyal bağlantılarını kontrol et.','Gerekirse sensörü uygun ürünle temizle veya doğrulanmış arızada değiştir; veriyi tekrar izle.'], caution:'MAF sensörüne gelişigüzel solvent veya mekanik temas uygulama.'},
 P0135:{ summary:'Bank 1 sensör 1 oksijen sensörünün ısıtıcı devresinde elektriksel hata algılandı.', first:'Sensör öncesinde sigorta, besleme, şase ve kablo tesisatını kontrol et.', steps:['Araçtaki Bank 1 Sensör 1 konumunu doğrula.','Isıtıcı devresi sigortası, besleme ve şaseyi ölç.','Kabloyu egzoz ısısı ve sürtünme hasarı açısından incele.','Sensör direncini üretici değerleriyle karşılaştır; onarım sonrası kodun dönmediğini doğrula.'], caution:'Egzoz ve sensörler sıcakken çalışma.'},
 P0500:{ summary:'Araç hızı sinyali beklenen biçimde alınamıyor.', first:'Hız verisinin hangi modülden geldiğini araç şemasında belirle; sensör, kablo ve ABS kaynaklarını ayır.', steps:['Gösterge hızı ve ABS/PCM canlı hız verilerini karşılaştır.','İlgili tekerlek hız sensörlerini ve bağlantılarını kontrol et.','Tesisat, konnektör ve sensör beslemesini ölç.','Onarım sonrası farklı hızlarda sinyal sürekliliğini doğrula.'], caution:'ABS veya hız göstergesi etkileniyorsa sürüş güvenliğini önceliklendir.'},
 P0016:{ summary:'Krank ve eksantrik mili konum sinyalleri arasında beklenen zamanlama uyuşmuyor.', first:'Mekanik zamanlamayı, yağ seviyesi/kalitesini ve sensör sinyallerini sırayla kontrol et.', steps:['Motor yağ seviyesi ve uygunluğunu kontrol et.','İlgili VVT kodlarını ve kam açılarını canlı veride incele.','Krank/eksantrik sinyallerini ve kablo bağlantılarını test et.','Gerekirse mekanik zamanlamayı üretici işaretlerine göre doğrula.'], caution:'Zincir/kayış zamanlaması şüphesinde motoru zorlamamak gerekir.'},
 P0430:{ summary:'Bank 2 katalizör verimliliği beklenen eşiğin altında ölçüldü.', first:'P0420 ile benzer teşhis yolu izlenir; fakat Bank 2 sensörleri ve egzoz hattı değerlendirilir.', steps:['Önce Bank 2 tekleme ve karışım kodlarını çöz.','Bank 2 egzoz hattında kaçak ve sensör tesisatı ara.','Ön/arka oksijen sensörü verilerini ve yakıt düzeltmelerini karşılaştır.','Konvertör kararını ölçümle doğrula; onarım sonrası monitörü izle.'], caution:'Bank 1 ve Bank 2 taraflarını karıştırma; motor yerleşimini doğrula.'}
};
