const simple = (route,title,deck,sections) => write(route,page({title:`${title} | OBDKODU`,description:deck,route,crumbs:[{name:title,path:route}],body:`<section class="page-hero"><div class="wrap"><span class="eyebrow">OBDKODU</span><h1>${e(title)}</h1><p>${e(deck)}</p></div></section><section class="section"><div class="wrap simple-content">${sections.map(([h,content])=>`<section><h2>${e(h)}</h2><p>${content}</p></section>`).join('')}</div></section>`}));
simple('/hakkimizda/','Hakkımızda','Arıza kodunu sadeleştiren Türkçe bir başvuru noktası.',[
 ['Neden OBDKODU?','Bir kod görüldüğünde en kolay ama en pahalı hata, adı geçen parçayı hemen değiştirmektir. OBDKODU kodun ne anlattığını, hangi belirtilerle ilişkili olabileceğini ve nasıl doğrulanacağını anlaşılır sırayla sunar.'],
 ['İçerik yaklaşımı','Dizin geniş tutulur; ayrıntılı rehberler yalnızca gözden geçirilmiş kodlar için yayınlanır. Her rehberde kodun kesin parça teşhisi olmadığı açıkça belirtilir. <a href="/yontem-ve-kaynaklar/">Yöntem ve kaynaklara bakın →</a>'],
 ['Bağımsız bilgi','OBDKODU bir araç servisi veya resmi standart kurumu değildir. Araç güvenliğini etkileyen konularda üretici dokümanı ve eğitimli teknisyen değerlendirmesi esas alınır.']
]);
simple('/yontem-ve-kaynaklar/','Yöntem ve kaynaklar','Kod dizininin kapsamı, içerik seçimi ve kaynakların nasıl kullanıldığı.',[
 ['Dizin ve ayrıntılı rehberler',`Kod dizini ${countLabel} farklı kod kaydı içerir. Bunların ${genericCount} tanesi OBDex genel kodlarıdır; 3.551 kayıt için yerel Türkçe ad bulunur. Bazı Türkçe kayıtlar genel kod kapsamı dışındadır ve üreticiye özgü olabilir. Ayrıntılı sayfalar yalnızca seçilmiş ${guides.length} kod için hazırlanır. Dizin kaydı tek başına tüm marka ve modellere geçerli onarım anlamına gelmez.`],
 ['Açık veri','<a href="https://github.com/foerbsnavi/obdex" rel="noopener noreferrer" target="_blank">OBDex açık veri projesi</a> genel OBD-II kodları için CC0 veri yayımlar. Türkçe adlar ve ayrıntılı rehber başlangıcı aynı bilgisayardaki önceki obdkodu-web projesinden alınmıştır. Türkçe karşılığı olmayan genel kodlar İngilizce kaynak adıyla gösterilir.'],
 ['Teşhis ilkesi','Kod, belirti, donma karesi ve canlı veri birlikte yorumlanır. Ölçümden önce parça değişimi önerilmez. İçerikler servis kılavuzu veya profesyonel teşhisin yerine geçmez.'],
 ['Teknik ve SEO kaynakları','Yapılandırılmış veri ve site haritası uygulamaları <a href="https://developers.google.com/search/docs/appearance/structured-data/intro-structured-data" rel="noopener noreferrer" target="_blank">Google Search Central</a> ve <a href="https://developers.google.com/search/docs/crawling-indexing/sitemaps/build-sitemap" rel="noopener noreferrer" target="_blank">sitemap rehberi</a> esas alınarak hazırlanmıştır.']
]);
simple('/iletisim/','İletişim','Kod açıklamalarına ilişkin düzeltme ve önerilerinizi iletin.',[
 ['Geri bildirim','Bir kod açıklamasında hata fark ettiyseniz kodu, araç marka/model/motor bilgisini ve varsa üretici dokümanı bağlantısını ekleyerek bize yazın.'],
 ['E-posta','<a href="mailto:birakiyoruziletisim@gmail.com">birakiyoruziletisim@gmail.com</a>'],
 ['Acil durum','Bu site üzerinden araç arıza teşhisi veya acil yol yardımı verilmez. Sürüş güvenliği riski varsa güvenli yerde durup yetkili destek alın.']
]);
simple('/gizlilik/','Gizlilik','Bu statik sitenin veri kullanımına ilişkin kısa açıklama.',[
 ['Arama verisi','Kod eşleştirmesi tarayıcınızda yapılır. Paylaşılabilir arama bağlantısı için yazdığınız metin URL sorgu parametresine eklenir; sayfa isteğinde barındırma sağlayıcısının standart erişim kayıtlarında görünebilir. Arama kutusuna kişisel bilgi yazmayın.'],
 ['Çerezler ve dış kaynaklar','Bu sürümde analitik veya reklam çerezi yoktur. Yazı tipleri site üzerinde barındırılır; görüntüleme için üçüncü taraf font isteği yapılmaz.'],
 ['E-posta','E-posta bağlantısını kullanırsanız iletinizi kendi e-posta uygulamanız gönderir. Mesajınızın işlenmesi için ayrıca bir gizlilik bildirimi gerekebilir; yayın öncesinde gerçek işletme bilgilerinize göre bu metni güncelleyin.']
]);

const routes=['/','/ariza-kodlari/','/kodlari-birlikte-yorumla/',...categories.map(c=>`/ariza-kodlari/${c.id.toLowerCase()}/`),'/sistemler/','/rehber/',...guideItems.map(g=>`/rehber/${g.slug}/`),'/sss/','/hakkimizda/','/yontem-ve-kaynaklar/','/iletisim/','/gizlilik/',...guides.map(g=>`/ariza-kodlari/${g.code.toLowerCase()}/`)];
fs.writeFileSync(path.join(out,'sitemap.xml'),`<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${routes.map(r=>`  <url><loc>${url(r)}</loc></url>`).join('\n')}\n</urlset>\n`);
fs.writeFileSync(path.join(out,'robots.txt'),`User-agent: *\nAllow: /\nSitemap: ${url('/sitemap.xml')}\n`);
const deployDir=path.join(root,'deploy');
fs.mkdirSync(deployDir,{recursive:true});
const legacyRules=[
 '# Include inside the HTTPS www.obdkodu.com server block before the static location.',
 '# Existing indexed code URLs get direct, permanent redirects to the new guide.',
 ...guides.map(g=>`rewrite (?i)^/kod/${g.code}/?$ /ariza-kodlari/${g.code.toLowerCase()}/ permanent;`),
 'location ~* ^/kod/([PBCU][0-9A-F]{4})/?$ { return 301 https://www.obdkodu.com/ariza-kodlari/?q=$1; }',
 'location = /arama { return 301 /ariza-kodlari/; }',
 'location = /hakkinda { return 301 /hakkimizda/; }',
 'location = /kaynaklar-ve-metodoloji { return 301 /yontem-ve-kaynaklar/; }',
 'location = /gizlilik-politikasi { return 301 /gizlilik/; }',
 'location = /sistem { return 301 /sistemler/; }',
 ''
];
fs.writeFileSync(path.join(deployDir,'nginx-code-redirects.conf'),legacyRules.join('\n'));
const redirectRows=[
 ['source','destination','status'],
 ...guides.map(g=>[`/kod/${g.code}`,`/ariza-kodlari/${g.code.toLowerCase()}/`,301]),
 ['/arama','/ariza-kodlari/',301],
 ['/hakkinda','/hakkimizda/',301],
 ['/kaynaklar-ve-metodoloji','/yontem-ve-kaynaklar/',301],
 ['/gizlilik-politikasi','/gizlilik/',301],
 ['/sistem','/sistemler/',301]
];
fs.writeFileSync(path.join(deployDir,'redirects.csv'),redirectRows.map(row=>row.join(',')).join('\n')+'\n');
const apacheRules=[
 '# Apache server-context rules. Include after RewriteEngine On.',
 ...guides.map(g=>`RewriteRule ^/kod/${g.code}/?$ /ariza-kodlari/${g.code.toLowerCase()}/ [R=301,L,NC]`),
 ...guides.map(g=>`RewriteRule ^/kod/${g.code}/.+$ /ariza-kodlari/${g.code.toLowerCase()}/ [R=301,L,NC]`),
 'RewriteRule ^/kod/([PBCU][0-9A-F]{4})/.+$ /kod/$1 [R=301,L,NC]',
 'RewriteRule ^/kod/([PBCU][0-9A-F]{4})/?$ http://127.0.0.1:3000/kod/$1 [P,L,NC]',
 'RewriteRule ^/arama/?$ /ariza-kodlari/ [R=301,L,NC]',
 'RewriteRule ^/hakkinda/?$ /hakkimizda/ [R=301,L,NC]',
 'RewriteRule ^/kaynaklar-ve-metodoloji/?$ /yontem-ve-kaynaklar/ [R=301,L,NC]',
 'RewriteRule ^/gizlilik-politikasi/?$ /gizlilik/ [R=301,L,NC]',
 'RewriteRule ^/sistem/?$ /sistemler/ [R=301,L,NC]',
 'RewriteRule ^/api/search/?$ http://127.0.0.1:3000/api/search [P,L,NC]',
 'RewriteRule ^/(marka|gosterge-paneli|sistem|kullanim-kosullari|css|js|images)(/.*)?$ http://127.0.0.1:3000%{REQUEST_URI} [P,L,NC]',
 ''
];
fs.writeFileSync(path.join(deployDir,'apache-route-rules.conf'),apacheRules.join('\n'));
fs.writeFileSync(path.join(out,'404.html'),page({title:'Sayfa bulunamadı | OBDKODU',description:'Aradığınız sayfa bulunamadı. OBD arıza kodu dizinine dönün.',route:'/404/',noindex:true,body:`<section class="notfound wrap"><span class="eyebrow">404 / SAYFA BULUNAMADI</span><h1>Bu yol bir yere<br><em>çıkmıyor.</em></h1><p>Kodda küçük bir yazım hatası olabilir. Dizinden yeniden aramayı deneyin.</p>${cta('Kod dizinine dön','/ariza-kodlari/')}</section>`}));
console.log(`Built ${routes.length} indexable pages and 1 error page in ${out}`);
